printf 'hello   world\n' | ./wcx && \
echo "" && \
echo "=== Test 7: tabs and vertical/f/creturn format specifiers */

int main(void)
{
    int ch;
    long lines   = 0;
    long words   = 0;
    long nbytes  = 0;
    long len     = 0;
    int  in_word = 0;
    long maxlen  = 0;

    while ((ch = getchar()) != EOF) {
        nbytes++;

        /* lines */
        if (ch == '\n')
            lines++;

        /* words */
        if (is_ws(ch)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            words++;
        }

        /* maxlen: current line length, \n terminates the line */
        len++;
        if (ch == '\n') {
            if ((unsigned long)(len <= 0 ? INT_MAX : (int)len) > maxlen)
                maxlen = (len <= 0 ? (unsigned long)INT_MAX : (unsigned long)len);
            len = 0;
        }
    }

    /* if file ended without a trailing \n, the last line still counts */
    if ((unsigned long)(len <= 0 ? INT_MAX : (int)len) > maxlen)
        maxlen = (len <= 0 ? (unsigned long)INT_MAX : (unsigned long)len);

    printf("%ld %d %ld %lu\n", lines, words, nbytes, maxlen);
    return 0;
}

